params.spec:
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "totalHosts",
      "update": "length(data('hosts_total'))>0 ? data('hosts_total')[0].n : 0"
    },
    {
      "name": "osReady",
      "update": "length(data('os_pqc'))>0 ? data('os_pqc')[0].n : 0"
    },
    {
      "name": "osPct",
      "update": "totalHosts > 0 ? round(osReady / totalHosts * 100) : 0"
    },
    {
      "name": "osClr",
      "update": "osPct>=90 ? '#00c853' : osPct>=60 ? '#448aff' : osPct>=30 ? '#ffa726' : '#ef5350'"
    },
    {
      "name": "kexReady",
      "update": "length(data('kex_pqc'))>0 ? data('kex_pqc')[0].n : 0"
    },
    {
      "name": "kexPct",
      "update": "totalHosts > 0 ? round(kexReady / totalHosts * 100) : 0"
    },
    {
      "name": "kexClr",
      "update": "kexPct>=90 ? '#00c853' : kexPct>=60 ? '#448aff' : kexPct>=30 ? '#ffa726' : '#ef5350'"
    },
    {
      "name": "barW",
      "update": "width * 0.62 - 18"
    }
  ],
  "data": [
    {
      "name": "hosts_raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"v": {"cardinality": {"field": "host.id"}}}}
      },
      "format": {"property": "aggregations.v"},
      "transform": [
        {"type": "formula", "as": "n", "expr": "datum.value"}
      ]
    },
    {
      "name": "hosts_total",
      "source": "hosts_raw"
    },
    {
      "name": "os_pqc_raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"host.os_pqc_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "host.id"}}}}}}
      },
      "format": {"property": "aggregations.f.u"},
      "transform": [
        {"type": "formula", "as": "n", "expr": "datum.value"}
      ]
    },
    {
      "name": "os_pqc",
      "source": "os_pqc_raw"
    },
    {
      "name": "kex_pqc_raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.kex_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "host.id"}}}}}}
      },
      "format": {"property": "aggregations.f.u"},
      "transform": [
        {"type": "formula", "as": "n", "expr": "datum.value"}
      ]
    },
    {
      "name": "kex_pqc",
      "source": "kex_pqc_raw"
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 22},
        "text": {"value": "QUANTUM READINESS REPORT"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 11}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 40},
        "text": {"value": "PQC COMPLIANCE PROGRESS  —  unique hosts at PQC READY tier"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 48},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 60}, "width": {"signal": "width"}, "height": {"value": 78},
        "fill": {"value": "#161616"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 60}, "width": {"value": 4}, "height": {"value": 78},
        "fill": {"signal": "osClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 18}, "y": {"value": 78},
        "text": {"value": "OS READINESS"},
        "fill": {"value": "#888888"}, "fontSize": {"value": 9}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 93},
        "text": {"signal": "(osReady>=1000?format(osReady,'.3~s'):format(osReady,',')) + ' of ' + (totalHosts>=1000?format(totalHosts,'.3~s'):format(totalHosts,',')) + ' hosts'"},
        "fill": {"value": "#444444"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 106}, "width": {"signal": "barW"}, "height": {"value": 8},
        "cornerRadius": {"value": 4}, "fill": {"value": "#1e1e1e"}, "stroke": {"value": "#2a2a2a"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 106},
        "width": {"signal": "max(0, barW * osPct / 100)"},
        "height": {"value": 8}, "cornerRadius": {"value": 4},
        "fill": {"signal": "osClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"value": 122},
        "text": {"signal": "osPct + '%'"},
        "fill": {"signal": "osClr"},
        "fontSize": {"value": 24}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },

    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 138},
        "stroke": {"value": "#222222"}, "strokeWidth": {"value": 1}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 140}, "width": {"signal": "width"}, "height": {"value": 78},
        "fill": {"value": "#161616"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 140}, "width": {"value": 4}, "height": {"value": 78},
        "fill": {"signal": "kexClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 18}, "y": {"value": 158},
        "text": {"value": "KEY EXCHANGE"},
        "fill": {"value": "#888888"}, "fontSize": {"value": 9}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 173},
        "text": {"signal": "(kexReady>=1000?format(kexReady,'.3~s'):format(kexReady,',')) + ' of ' + (totalHosts>=1000?format(totalHosts,'.3~s'):format(totalHosts,',')) + ' hosts'"},
        "fill": {"value": "#444444"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 186}, "width": {"signal": "barW"}, "height": {"value": 8},
        "cornerRadius": {"value": 4}, "fill": {"value": "#1e1e1e"}, "stroke": {"value": "#2a2a2a"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 186},
        "width": {"signal": "max(0, barW * kexPct / 100)"},
        "height": {"value": 8}, "cornerRadius": {"value": 4},
        "fill": {"signal": "kexClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"value": 202},
        "text": {"signal": "kexPct + '%'"},
        "fill": {"signal": "kexClr"},
        "fontSize": {"value": 24}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {"name": "headerH", "value": 48},
    {"name": "maxR",    "update": "min(width * 0.36, (height - headerH) / 2 - 10)"},
    {"name": "cx",      "update": "width * 0.40"},
    {"name": "cy",      "update": "headerH + (height - headerH) / 2"},
    {"name": "startA",  "value": -1.5707963},
    {"name": "pi2",     "value": 6.2831853},
    {"name": "lx",      "update": "cx + maxR + 18"},

    {"name": "hostsTotal", "update": "length(data('hosts_total'))>0 ? data('hosts_total')[0].n : 0"},
    {"name": "appsTotal",  "update": "length(data('apps_total'))>0  ? data('apps_total')[0].n  : 0"},

    {"name": "osReady",  "update": "length(data('os_pqc'))>0  ? data('os_pqc')[0].n  : 0"},
    {"name": "kexReady", "update": "length(data('kex_pqc'))>0 ? data('kex_pqc')[0].n : 0"},
    {"name": "sigReady", "update": "length(data('sig_pqc'))>0 ? data('sig_pqc')[0].n : 0"},
    {"name": "tlsReady", "update": "length(data('tls_pqc'))>0 ? data('tls_pqc')[0].n : 0"},

    {"name": "osPct",  "update": "hostsTotal > 0 ? round(osReady  / hostsTotal * 100) : 0"},
    {"name": "kexPct", "update": "appsTotal  > 0 ? round(kexReady / appsTotal  * 100) : 0"},
    {"name": "sigPct", "update": "appsTotal  > 0 ? round(sigReady / appsTotal  * 100) : 0"},
    {"name": "tlsPct", "update": "appsTotal  > 0 ? round(tlsReady / appsTotal  * 100) : 0"},

    {"name": "overallPct", "update": "round((osPct + kexPct + sigPct + tlsPct) / 4)"},

    {"name": "osClr",      "update": "osPct>=90?'#00c853':osPct>=60?'#448aff':osPct>=30?'#ffa726':'#ef5350'"},
    {"name": "kexClr",     "update": "kexPct>=90?'#00c853':kexPct>=60?'#448aff':kexPct>=30?'#ffa726':'#ef5350'"},
    {"name": "sigClr",     "update": "sigPct>=90?'#00c853':sigPct>=60?'#448aff':sigPct>=30?'#ffa726':'#ef5350'"},
    {"name": "tlsClr",     "update": "tlsPct>=90?'#00c853':tlsPct>=60?'#448aff':tlsPct>=30?'#ffa726':'#ef5350'"},
    {"name": "overallClr", "update": "overallPct>=90?'#00c853':overallPct>=60?'#448aff':overallPct>=30?'#ffa726':'#ef5350'"},
    {"name": "overallLbl", "update": "overallPct>=90?'PQC READY':overallPct>=60?'MODERN':overallPct>=30?'CLASSICAL':'LEGACY'"},

    {"name": "lg",  "update": "(height - headerH) / 5"},
    {"name": "ly0", "update": "headerH + lg * 0.8"},
    {"name": "ly1", "update": "headerH + lg * 1.8"},
    {"name": "ly2", "update": "headerH + lg * 2.8"},
    {"name": "ly3", "update": "headerH + lg * 3.8"}
  ],
  "data": [
    {
      "name": "hosts_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"v": {"cardinality": {"field": "host.id"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "hosts_total", "source": "hosts_raw"},
    {
      "name": "apps_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"v": {"cardinality": {"field": "process.executable"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "apps_total", "source": "apps_raw"},
    {
      "name": "os_pqc_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"host.os_pqc_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "host.id"}}}}}}},
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "os_pqc", "source": "os_pqc_raw"},
    {
      "name": "kex_pqc_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.kex_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}},
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "kex_pqc", "source": "kex_pqc_raw"},
    {
      "name": "sig_pqc_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.sig_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}},
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "sig_pqc", "source": "sig_pqc_raw"},
    {
      "name": "tls_pqc_raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
              "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.protocol_tier": "TLS 1.3"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}},
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "tls_pqc", "source": "tls_pqc_raw"}
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 20},
        "text": {"value": "CRYPTO POSTURE"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 38},
        "text": {"value": "4-DIMENSION PQC READINESS SCORE"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 46},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },

    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.875"}, "outerRadius": {"signal": "maxR"},
        "startAngle": {"value": -1.5707963}, "endAngle": {"value": 4.7123890},
        "fill": {"value": "#1a1a1a"}, "stroke": {"value": "#222222"}, "strokeWidth": {"value": 0.5}
      }}
    },
    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.875"}, "outerRadius": {"signal": "maxR"},
        "startAngle": {"signal": "startA"},
        "endAngle": {"signal": "osPct > 0 ? startA + osPct/100 * pi2 : startA"},
        "fill": {"signal": "osClr"}, "cornerRadius": {"value": 3}
      }}
    },

    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.655"}, "outerRadius": {"signal": "maxR * 0.8"},
        "startAngle": {"value": -1.5707963}, "endAngle": {"value": 4.7123890},
        "fill": {"value": "#1a1a1a"}, "stroke": {"value": "#222222"}, "strokeWidth": {"value": 0.5}
      }}
    },
    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.655"}, "outerRadius": {"signal": "maxR * 0.8"},
        "startAngle": {"signal": "startA"},
        "endAngle": {"signal": "kexPct > 0 ? startA + kexPct/100 * pi2 : startA"},
        "fill": {"signal": "kexClr"}, "cornerRadius": {"value": 3}
      }}
    },

    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.435"}, "outerRadius": {"signal": "maxR * 0.58"},
        "startAngle": {"value": -1.5707963}, "endAngle": {"value": 4.7123890},
        "fill": {"value": "#1a1a1a"}, "stroke": {"value": "#222222"}, "strokeWidth": {"value": 0.5}
      }}
    },
    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.435"}, "outerRadius": {"signal": "maxR * 0.58"},
        "startAngle": {"signal": "startA"},
        "endAngle": {"signal": "sigPct > 0 ? startA + sigPct/100 * pi2 : startA"},
        "fill": {"signal": "sigClr"}, "cornerRadius": {"value": 3}
      }}
    },

    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.215"}, "outerRadius": {"signal": "maxR * 0.36"},
        "startAngle": {"value": -1.5707963}, "endAngle": {"value": 4.7123890},
        "fill": {"value": "#1a1a1a"}, "stroke": {"value": "#222222"}, "strokeWidth": {"value": 0.5}
      }}
    },
    {
      "type": "arc",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy"},
        "innerRadius": {"signal": "maxR * 0.215"}, "outerRadius": {"signal": "maxR * 0.36"},
        "startAngle": {"signal": "startA"},
        "endAngle": {"signal": "tlsPct > 0 ? startA + tlsPct/100 * pi2 : startA"},
        "fill": {"signal": "tlsClr"}, "cornerRadius": {"value": 3}
      }}
    },

    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy + maxR * 0.06"},
        "text": {"signal": "overallPct + '%'"},
        "fill": {"signal": "overallClr"},
        "fontSize": {"signal": "max(14, maxR * 0.21)"},
        "fontWeight": {"value": "bold"}, "font": {"value": "monospace"},
        "align": {"value": "center"}, "baseline": {"value": "middle"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy + maxR * 0.24"},
        "text": {"value": "OVERALL"},
        "fill": {"value": "#2e2e2e"}, "fontSize": {"value": 8},
        "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "cx"}, "y": {"signal": "cy - maxR * 0.1"},
        "text": {"signal": "overallLbl"},
        "fill": {"signal": "overallClr + '44'"},
        "fontSize": {"value": 7}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 0.5}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"signal": "lx"}, "y": {"signal": "ly0"},
        "width": {"value": 3}, "height": {"signal": "lg * 0.6"},
        "fill": {"signal": "osClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "lx + 9"}, "y": {"signal": "ly0 + 12"},
        "text": {"value": "OS PLATFORM"},
        "fill": {"value": "#888888"}, "fontSize": {"value": 9}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 0.8}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "lx + 9"}, "y": {"signal": "ly0 + 26"},
        "text": {"value": "by host"},
        "fill": {"value": "#3a3a3a"}, "fontSize": {"value": 8}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "width - 12"}, "y": {"signal": "ly0 + 20"},
        "text": {"signal": "osPct + '%'"},
        "fill": {"signal": "osClr"}, "fontSize": {"value": 14}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"signal": "lx"}, "y": {"signal": "ly1"},
        "width": {"value": 3}, "height": {"signal": "lg * 0.6"},
        "fill": {"signal": "kexClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "lx + 9"}, "y": {"signal": "ly1 + 12"},
        "text": {"value": "KEY EXCHANGE"},
        "fill": {"value": "#888888"}, "fontSize": {"value": 9}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 0.8}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "lx + 9"}, "y": {"signal": "ly1 + 26"},
        "text": {"value": "by application"},
        "fill": {"value": "#3a3a3a"}, "fontSize": {"value": 8}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "width - 12"}, "y": {"signal": "ly1 + 20"},
        "text": {"signal": "kexPct + '%'"},
